const SIDEBAR_ZONE = '[data-tree-group]:has([data-slot="sidebar"])'

// Dashed corner brackets around a box, drawn with gradients so no markup is needed.
const bracket = color => {
  const h = `linear-gradient(90deg, ${color} 0 3px, transparent 3px 5px, ${color} 5px 8px, transparent 8px 10px, ${color} 10px 12px)`
  const v = `linear-gradient(180deg, ${color} 0 3px, transparent 3px 5px, ${color} 5px 8px)`

  return {
    image: [h, h, h, h, v, v, v, v].join(','),
    size: '12px 1px, 12px 1px, 12px 1px, 12px 1px, 1px 8px, 1px 8px, 1px 8px, 1px 8px',
    position: 'left top, right top, left bottom, right bottom, left top, right top, left bottom, right bottom'
  }
}

const B = bracket('var(--skin-ink)')

function cssFor(THEME) {
  const V = THEME.vars
  const ART = THEME.art
  // Prefix match: picking an accent colour renames the active theme to `<name>-accent-<hex>`.
  const T = `:root[data-hermes-theme^="${THEME.name}"]`

  return `
${T} {
  --skin-ink: ${V.ink};
  --skin-dim: ${V.dim};
  --skin-rule: color-mix(in srgb, ${V.rule} 32%, transparent);
  --skin-dots: radial-gradient(circle at center, ${V.wordmarkDots} 0.55px, transparent 1px);
  --skin-art-floor: 250px;
}

${T} ${SIDEBAR_ZONE} > [data-panel-header] {
  position: relative;
  height: 262px !important;
}

${T} ${SIDEBAR_ZONE} > [data-panel-header]::before {
  content: '';
  position: absolute;
  inset: 0 0 18px 0;
  background: url("${ART.top}") center 0 / 320px auto no-repeat;
  image-rendering: pixelated;
  -webkit-mask-image: linear-gradient(to bottom, #000 72%, transparent);
  mask-image: linear-gradient(to bottom, #000 72%, transparent);
  pointer-events: none;
}

${T} ${SIDEBAR_ZONE} > [data-panel-header] > [data-window-drag-handle] {
  z-index: 1;
}

${T} ${SIDEBAR_ZONE} > [data-panel-header] > [data-zone-tabstrip] {
  z-index: 1;
  background: transparent;
  padding-inline: 14px;
  gap: 10px;
}

${T} [data-tree-group]:not(:has([data-slot="sidebar"])) > [data-panel-header] > [data-zone-tabstrip] {
  padding-left: 10px;
}

${T} [data-slot="sidebar"] {
  position: relative;
  isolation: isolate;
  border-right: 1px dotted var(--skin-rule) !important;
}

${T} [data-slot="sidebar"]::before {
  content: '';
  position: absolute;
  z-index: -1;
  inset: auto 0 0 0;
  height: var(--skin-art-floor);
  background: url("${ART.bottom}") center bottom / 320px auto no-repeat;
  image-rendering: pixelated;
  -webkit-mask-image: linear-gradient(to bottom, transparent, #000 40%);
  mask-image: linear-gradient(to bottom, transparent, #000 40%);
  pointer-events: none;
}

/* the session list stops where the art starts fading in, and scrolls above it */
${T} [data-slot="sidebar"] [data-slot="sidebar-content"] > *:last-child {
  padding-bottom: var(--skin-art-floor);
}

${T} [data-slot="pane-tab"],
${T} [data-tree-tab] {
  font-family: var(--font-mono);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  border: 0 !important;
  box-shadow: none !important;
}

${T} [data-slot="pane-tab"][data-active="true"],
${T} [data-tree-tab][data-active="true"] {
  color: var(--skin-ink);
  background-color: transparent !important;
  background-image: ${B.image};
  background-size: ${B.size};
  background-position: ${B.position};
  background-repeat: no-repeat;
}

${T} [data-slot="pane-tab"][data-active="true"]::after,
${T} [data-tree-tab][data-active="true"]::after {
  display: none !important;
}

${T} [data-slot="pane-tab"][data-active="false"] {
  color: var(--skin-dim);
}

${T} [data-tree-group][data-window-top] > [data-panel-header] {
  border-bottom: 1px dotted var(--skin-rule);
}

${T} [data-sash-overlap] {
  opacity: 0;
}

${T} [data-slot="composer-surface"] {
  border: 1px dashed color-mix(in srgb, var(--skin-ink) 55%, transparent) !important;
  border-radius: 6px !important;
  background: ${V.surface} !important;
  box-shadow: none !important;
}

${T} [data-slot="kbd"] {
  font-family: var(--font-mono);
  background: transparent !important;
  border: 1px dashed color-mix(in srgb, var(--skin-ink) 60%, transparent) !important;
  color: var(--skin-ink) !important;
}

${T} [data-slot="sidebar-input"],
${T} [data-slot="sidebar"] input[type="search"] {
  border: 0 !important;
  border-bottom: 1px dotted var(--skin-rule) !important;
  border-radius: 0 !important;
  background: transparent !important;
}

/* empty chat: the hero art behind the wordmark */
${T} [data-slot="aui_intro"] {
  position: relative;
  isolation: isolate;
  overflow: visible;
}

${T} [data-slot="aui_intro"]::before {
  content: '';
  position: absolute;
  z-index: -1;
  left: 50%;
  bottom: calc(100% - 175px);
  width: 900px;
  height: 450px;
  max-width: 100%;
  transform: translateX(-50%);
  background: url("${ART.hero}") center bottom / contain no-repeat;
  image-rendering: pixelated;
  pointer-events: none;
}

${T} [data-slot="aui_intro"]::after {
  content: '';
  position: absolute;
  z-index: -1;
  left: 4%;
  right: 4%;
  top: 40px;
  height: 120px;
  background:
    linear-gradient(90deg, var(--skin-rule) 50%, transparent 50%) left 0 / 6px 1px repeat-x,
    linear-gradient(90deg, var(--skin-rule) 50%, transparent 50%) left 100% / 6px 1px repeat-x;
  pointer-events: none;
}

${T} .wordmark {
  mix-blend-mode: normal !important;
}

${T} .wordmark > span:not([aria-hidden]) > span {
  color: transparent;
  background:
    var(--skin-dots) 0 0 / 3px 3px,
    linear-gradient(180deg, ${V.wordmark.join(', ')});
  -webkit-background-clip: text;
  background-clip: text;
  filter: drop-shadow(0 0 1px ${V.wordmarkShadow});
}

${T} [data-slot="aui_intro"] p:not(.wordmark) {
  font-family: var(--font-mono);
  font-size: 0.9rem;
  letter-spacing: 0.02em;
  line-height: 1.7;
  color: var(--skin-ink);
  max-width: 44ch;
  margin-inline: auto;
}

${T} [data-slot="composer-surface"] button[data-variant="default"] {
  background: ${V.send} !important;
  color: ${V.sendInk} !important;
}
`
}

const desktopTheme = THEME => ({
  name: THEME.name,
  label: THEME.label,
  description: THEME.description,
  // Same palette for both modes so the art never lands on a light ground.
  colors: THEME.colors,
  darkColors: THEME.colors,
  typography: THEME.typography,
  terminal: THEME.terminal,
  darkTerminal: THEME.terminal,
  customCSS: cssFor(THEME)
})

export default {
  id: 'hermes-desktop-skins',
  name: 'Hermes Desktop Skins',
  register(ctx) {
    ctx.registerMany(THEMES.map(THEME => ({ id: THEME.name, area: THEMES_AREA, data: desktopTheme(THEME) })))
  }
}
